<template><div class="space-y-7"><AppPageHeader eyebrow="B2B" title="Operação corporativa" description="Pipeline comercial, empresas clientes e acesso às rotinas de colaboradores, vagas e matrículas."><template #actions><router-link to="/companies" class="inline-flex items-center gap-2 rounded-xl border border-slate-200 bg-white px-4 py-2.5 text-sm font-semibold text-slate-700 shadow-sm"><NavIcon name="building"/>Cadastro de empresas</router-link></template></AppPageHeader><div v-if="error" class="rounded-2xl border border-red-200 bg-red-50 p-4 text-sm text-red-700">{{ error }}</div>
<section class="premium-card overflow-hidden"><div class="flex items-center justify-between border-b border-slate-100 px-5 py-4 sm:px-6"><div><p class="premium-kicker">Pipeline</p><h2 class="mt-1 font-bold text-slate-900">Solicitações de treinamento</h2></div><span class="rounded-full bg-slate-100 px-3 py-1 text-xs font-bold text-slate-500">{{ requests.length }}</span></div><div v-if="loading" class="p-8 text-sm text-slate-400">Carregando…</div><div v-else-if="!requests.length" class="m-5 rounded-2xl border border-dashed border-slate-200 bg-slate-50 p-8 text-center text-sm text-slate-400">Nenhuma solicitação corporativa.</div><div v-else class="divide-y divide-slate-100"><div v-for="lead in requests" :key="lead.id" class="grid gap-4 p-5 sm:p-6 lg:grid-cols-[1fr_220px] lg:items-center"><div><div class="flex flex-wrap items-center gap-2"><span class="flex h-9 w-9 items-center justify-center rounded-xl bg-blue-50 text-blue-700"><NavIcon name="briefcase"/></span><div><h3 class="font-bold text-slate-900">{{ lead.company_name }}</h3><p class="text-xs text-slate-400">{{ lead.contact_name }} · {{ lead.contact_email }}</p></div></div><div class="mt-3 flex flex-wrap gap-2 text-xs"><span class="rounded-full bg-slate-100 px-2.5 py-1 font-semibold text-slate-600">{{ lead.course_interest || 'Treinamento não especificado' }}</span><span class="rounded-full bg-slate-100 px-2.5 py-1 font-semibold text-slate-600">{{ lead.employee_count || '—' }} colaboradores</span></div><p v-if="lead.message" class="mt-3 max-w-3xl text-sm leading-6 text-slate-500">{{ lead.message }}</p></div><div><label class="mb-1.5 block text-[10px] font-bold uppercase tracking-wider text-slate-400">Etapa do pipeline</label><select :value="lead.status" class="w-full" @change="changeStatus(lead,$event.target.value)"><option v-for="status in statuses" :key="status">{{ status }}</option></select></div></div></div></section>
<section><div class="mb-4 flex items-end justify-between"><div><p class="premium-kicker">Contas corporativas</p><h2 class="mt-1 text-lg font-bold text-slate-900">Empresas</h2></div><span class="text-xs font-semibold text-slate-400">{{ companies.length }} cadastradas</span></div><div class="grid gap-4 md:grid-cols-2 xl:grid-cols-3"><router-link v-for="company in companies" :key="company.id" :to="`/companies/${company.id}/operations`" class="premium-card premium-card-hover group p-5"><div class="flex items-start gap-3"><span class="flex h-11 w-11 items-center justify-center rounded-xl bg-[var(--brand-primary-soft)] text-[var(--brand-primary)]"><NavIcon name="building"/></span><div class="min-w-0"><p class="truncate font-bold text-slate-900">{{ company.trade_name || company.legal_name }}</p><p class="mt-1 text-xs text-slate-400">{{ company.cnpj }}</p></div></div><div class="mt-4 flex items-center justify-between"><span class="rounded-full bg-emerald-50 px-2.5 py-1 text-[10px] font-bold uppercase tracking-wider text-emerald-700">{{ company.status || 'ACTIVE' }}</span><span class="text-xs font-bold text-[var(--brand-primary)]">Abrir operação →</span></div></router-link></div></section></div></template>
<script setup>import{onMounted,ref}from'vue';import api from'../api/client';import{listCorporateRequests,updateCorporateRequest}from'../api/corporate';import AppPageHeader from'../components/AppPageHeader.vue';import NavIcon from'../components/NavIcon.vue';const requests=ref([]),companies=ref([]),loading=ref(true),error=ref('');const statuses=['NEW','CONTACTED','QUALIFIED','PROPOSAL_SENT','WON','LOST'];async function load(){loading.value=true;try{const[r,c]=await Promise.all([listCorporateRequests(),api.get('/api/v1/companies/')]);requests.value=r.data;companies.value=c.data}catch(e){error.value=e.response?.data?.detail||'Erro ao carregar operação corporativa.'}finally{loading.value=false}}async function changeStatus(lead,status){try{Object.assign(lead,(await updateCorporateRequest(lead.id,{status})).data)}catch(e){error.value=e.response?.data?.detail||'Não foi possível atualizar a solicitação.'}}onMounted(load)</script>
